import "server-only";

import { FeedUnit, FinanceModule, IncubationEggSource, PoultryBatchSource, PoultryMovementType, PoultrySaleType, Prisma } from "@prisma/client";
import { z } from "zod";

import { approximateFeedConsumptionKg, feedQuantityToKg, flockQuantity, hatchRate, movementDelta, poultryAgeDays, poultryReport, reconciliationDelta, saleTotal, transferProductionCost } from "@/features/poultry/calculations";
import { periodStart } from "@/features/family/calculations";
import { dateFromInput, todayInputValue } from "@/lib/dates";
import { prisma } from "@/lib/prisma";

type Db = Prisma.TransactionClient;
export type PoultryPeriod = "TODAY" | "WEEK" | "MONTH" | "YEAR" | "ALL";
const money = z.string().trim().regex(/^\d+(?:[.,]\d{1,4})?$/);
const positiveInt = z.coerce.number().int().positive();
const nonNegativeInt = z.coerce.number().int().min(0);
const date = z.string().regex(/^\d{4}-\d{2}-\d{2}$/);
const decimal = (value: string | number | Prisma.Decimal) => new Prisma.Decimal(typeof value === "string" ? value.replace(",", ".") : value);
const numberValue = (value: string | number | Prisma.Decimal | null | undefined) => value == null ? 0 : Number(value);
const optional = (value: FormDataEntryValue | null) => typeof value === "string" && value.trim() ? value.trim() : null;
const normalizedName = (value: string) => value.trim().replace(/\s+/g, " ");
const canonicalName = (value: string) => normalizedName(value).toLocaleLowerCase("ru-RU");

export const batchSchema = z.object({ name: z.string().trim().min(1).max(120), birdType: z.string().trim().min(1).max(80), breed: z.string().trim().max(80).nullable().optional(), breeds: z.array(z.object({ name: z.string().trim().max(80).nullable(), quantity: positiveInt })).max(8).optional(), startDate: date, acquisitionDate: date.optional(), ageAtAcquisitionDays: nonNegativeInt.nullable().optional(), quantity: positiveInt, source: z.nativeEnum(PoultryBatchSource), cashCost: money.nullable().optional(), productionValue: money.nullable().optional(), comment: z.string().trim().max(500).nullable() });
export const movementSchema = z.object({ batchId: z.string().cuid(), type: z.enum(["ADD", "MORTALITY", "FAMILY_USE", "ADJUSTMENT"]), quantity: positiveInt, operationDate: date, reason: z.string().trim().max(120).nullable().optional(), comment: z.string().trim().max(500).nullable() });
export const reconciliationSchema = z.object({ batchId: z.string().cuid(), actualQuantity: nonNegativeInt, operationDate: date, comment: z.string().trim().max(500).nullable() });
export const transferSchema = z.object({ sourceBatchId: z.string().cuid(), destinationBatchId: z.string().cuid().nullable(), destinationName: z.string().trim().max(120).nullable(), quantity: positiveInt, operationDate: date, comment: z.string().trim().max(500).nullable() }).refine((value) => value.destinationBatchId || value.destinationName, "Оберіть або створіть групу призначення.");
export const slaughterSchema = z.object({ batchId: z.string().cuid(), quantity: positiveInt, purpose: z.enum(["FAMILY", "SALE"]), carcassWeightKg: money.nullable(), operationDate: date, comment: z.string().trim().max(500).nullable() });
export const saleSchema = z.object({ saleType: z.nativeEnum(PoultrySaleType).default("LIVE_BIRD"), batchId: z.string().cuid().nullable(), slaughterId: z.string().cuid().nullable().optional(), buyer: z.string().trim().max(120).nullable(), buyerPhone: z.string().trim().max(40).nullable().optional(), itemName: z.string().trim().min(1).max(120), quantity: z.coerce.number().int().positive().nullable(), weightKg: money.nullable(), price: money.nullable(), totalAmount: money.nullable(), operationDate: date, comment: z.string().trim().max(500).nullable() }).superRefine((data, context) => { if (!data.quantity && !data.weightKg) context.addIssue({ code: "custom", message: "Вкажіть кількість або вагу." }); if (data.saleType === "LIVE_BIRD" && (!data.batchId || !data.quantity)) context.addIssue({ code: "custom", message: "Для живої птиці потрібні група і кількість." }); if (data.saleType === "EGGS" && !data.quantity) context.addIssue({ code: "custom", message: "Вкажіть кількість яєць." }); });
export const feedPurchaseSchema = z.object({ name: z.string().trim().min(1).max(120), type: z.string().trim().max(80).nullable(), unit: z.nativeEnum(FeedUnit).default("BAG"), quantity: money.optional(), bagSizeKg: money.nullable(), householdUnitName: z.string().trim().max(40).nullable().optional(), householdUnitKg: money.nullable().optional(), bags: positiveInt.optional(), totalAmount: money, deliveryAmount: money.nullable().optional(), supplier: z.string().trim().max(120).nullable().optional(), operationDate: date, comment: z.string().trim().max(500).nullable() });
export const feedUsageSchema = z.object({ lotId: z.string().cuid(), batchId: z.string().cuid().nullable(), purpose: z.enum(["FATTENING", "LAYERS", "GENERAL"]).nullable().optional(), unit: z.nativeEnum(FeedUnit).default("BAG"), quantity: money.optional(), bags: positiveInt.optional(), operationDate: date, comment: z.string().trim().max(500).nullable() });
export const feedRateSchema = z.object({ batchId: z.string().cuid(), productId: z.string().cuid(), unit: z.nativeEnum(FeedUnit), dailyQuantity: money, effectiveFrom: date, comment: z.string().trim().max(500).nullable() });
export const feedAdjustmentSchema = z.object({ productId: z.string().cuid(), actualKg: money, operationDate: date, comment: z.string().trim().max(500).nullable() });
export const feedProductSettingsSchema = z.object({ productId: z.string().cuid(), type: z.string().trim().max(80).nullable(), minimumStockKg: money });
export const feedProductCatalogSchema = z.object({ id: z.string().cuid().optional(), name: z.string().trim().min(1).max(120), type: z.string().trim().max(80).nullable().optional() });
export const feedUnitSettingsSchema = z.object({ productId: z.string().cuid(), bagSizeKg: money.nullable(), householdUnitName: z.string().trim().max(40).nullable(), householdUnitKg: money.nullable() });
export const poultryCategorySettingsSchema = z.object({ id: z.string().cuid().optional(), name: z.string().trim().min(1).max(80), icon: z.string().trim().max(12).nullable().optional() });
export const poultryBreedSettingsSchema = z.object({ id: z.string().cuid().optional(), name: z.string().trim().min(1).max(80) });
export const incubationSchema = z.object({ name: z.string().trim().min(1).max(120), birdType: z.string().trim().min(1).max(80), setDate: date, eggSource: z.nativeEnum(IncubationEggSource).default("OWN"), cashCost: money.nullable().optional(), productionCost: money.nullable().optional(), comment: z.string().trim().max(500).nullable(), items: z.array(z.object({ breed: z.string().trim().max(80).nullable(), setQuantity: positiveInt, comment: z.string().trim().max(500).nullable() })).min(1).max(8) });
export const incubationUpdateSchema = z.object({ itemId: z.string().cuid(), hatchDate: date, infertileQuantity: nonNegativeInt, lossQuantity: nonNegativeInt, hatchedQuantity: nonNegativeInt });
export const eggCollectionSchema = z.object({ batchId: z.string().cuid().nullable(), breed: z.string().trim().max(80).nullable(), quantity: positiveInt, operationDate: date, collector: z.string().trim().max(120).nullable(), comment: z.string().trim().max(500).nullable() });
export const operationalExpenseSchema = z.object({ categoryId: z.string().cuid(), batchId: z.string().cuid().nullable(), incubationBatchId: z.string().cuid().nullable().optional(), amount: money, operationDate: date, description: z.string().trim().min(1).max(500) });

async function poultryCategory(userId: string, id: string, kind: "INCOME" | "EXPENSE") { const category = await prisma.category.findFirst({ where: { id, module: FinanceModule.POULTRY, isArchived: false, OR: [{ userId }, { userId: null }] } }); if (!category || (category.kind !== kind && category.kind !== "BOTH")) throw new Error("Оберіть доступну категорію Птахівництва."); return category; }
async function categoryByName(userId: string, names: string[], kind: "INCOME" | "EXPENSE") { const category = await prisma.category.findFirst({ where: { name: { in: names }, module: FinanceModule.POULTRY, isArchived: false, OR: [{ userId }, { userId: null }] }, orderBy: { sortOrder: "asc" } }); if (!category) throw new Error("Системна категорія Птахівництва відсутня."); return poultryCategory(userId, category.id, kind); }
export async function getPoultryCategories(userId: string, includeArchived = false) { return prisma.category.findMany({ where: { module: FinanceModule.POULTRY, ...(includeArchived ? {} : { isArchived: false }), OR: [{ userId }, { userId: null }] }, include: { _count: { select: { transactions: true } } }, orderBy: [{ isArchived: "asc" }, { sortOrder: "asc" }, { name: "asc" }] }); }
async function assertUniquePoultryCategory(userId: string, name: string, exceptId?: string) { const categories = await prisma.category.findMany({ where: { module: "POULTRY", OR: [{ userId }, { userId: null }], ...(exceptId ? { id: { not: exceptId } } : {}) }, select: { name: true } }); if (categories.some((item) => canonicalName(item.name) === canonicalName(name))) throw new Error("Такая категория уже существует"); }
export async function createPoultryCategory(userId: string, input: z.infer<typeof poultryCategorySettingsSchema>) { const name = normalizedName(input.name); await assertUniquePoultryCategory(userId, name); const aggregate = await prisma.category.aggregate({ where: { module: "POULTRY", OR: [{ userId }, { userId: null }] }, _max: { sortOrder: true } }); return prisma.category.create({ data: { userId, module: "POULTRY", kind: "EXPENSE", name, icon: input.icon, sortOrder: (aggregate._max.sortOrder ?? 0) + 10 } }); }
export async function updatePoultryCategory(userId: string, input: z.infer<typeof poultryCategorySettingsSchema>) { if (!input.id) throw new Error("Категория не найдена"); const category = await prisma.category.findFirst({ where: { id: input.id, userId, module: "POULTRY" } }); if (!category) throw new Error("Системную категорию нельзя изменить"); const name = normalizedName(input.name); await assertUniquePoultryCategory(userId, name, category.id); return prisma.category.update({ where: { id: category.id }, data: { name, icon: input.icon } }); }
export async function setPoultryCategoryArchived(userId: string, id: string, isArchived: boolean) { const category = await prisma.category.findFirst({ where: { id, userId, module: "POULTRY" } }); if (!category) throw new Error("Системную категорию нельзя архивировать"); return prisma.category.update({ where: { id }, data: { isArchived } }); }
export async function movePoultryCategory(userId: string, id: string, direction: "UP" | "DOWN") { const category = await prisma.category.findFirst({ where: { id, userId, module: "POULTRY" } }); if (!category) throw new Error("Категория не найдена"); return prisma.category.update({ where: { id }, data: { sortOrder: { increment: direction === "UP" ? -11 : 11 } } }); }
export async function deleteUnusedPoultryCategory(userId: string, id: string) { const category = await prisma.category.findFirst({ where: { id, userId, module: "POULTRY" }, include: { _count: { select: { transactions: true } } } }); if (!category) throw new Error("Категория не найдена"); if (category._count.transactions) throw new Error("Используемую категорию можно только архивировать"); return prisma.category.delete({ where: { id } }); }

export async function getPoultryBreeds(userId: string, includeArchived = false) { return prisma.poultryBreed.findMany({ where: { userId, ...(includeArchived ? {} : { isArchived: false }) }, orderBy: [{ isArchived: "asc" }, { sortOrder: "asc" }, { name: "asc" }] }); }
async function assertUniquePoultryBreed(userId: string, name: string, exceptId?: string) { const breeds = await prisma.poultryBreed.findMany({ where: { userId, ...(exceptId ? { id: { not: exceptId } } : {}) }, select: { name: true } }); if (breeds.some((item) => canonicalName(item.name) === canonicalName(name))) throw new Error("Такая порода уже существует"); }
export async function createPoultryBreed(userId: string, input: z.infer<typeof poultryBreedSettingsSchema>) { const name = normalizedName(input.name); await assertUniquePoultryBreed(userId, name); const aggregate = await prisma.poultryBreed.aggregate({ where: { userId }, _max: { sortOrder: true } }); return prisma.poultryBreed.create({ data: { userId, name, sortOrder: (aggregate._max.sortOrder ?? 0) + 10 } }); }
export async function updatePoultryBreed(userId: string, input: z.infer<typeof poultryBreedSettingsSchema>) { if (!input.id) throw new Error("Порода не найдена"); const breed = await prisma.poultryBreed.findFirst({ where: { id: input.id, userId } }); if (!breed) throw new Error("Порода не найдена"); const name = normalizedName(input.name); await assertUniquePoultryBreed(userId, name, breed.id); return prisma.poultryBreed.update({ where: { id: breed.id }, data: { name } }); }
export async function setPoultryBreedArchived(userId: string, id: string, isArchived: boolean) { const breed = await prisma.poultryBreed.findFirst({ where: { id, userId } }); if (!breed) throw new Error("Порода не найдена"); return prisma.poultryBreed.update({ where: { id }, data: { isArchived } }); }
export async function movePoultryBreed(userId: string, id: string, direction: "UP" | "DOWN") { const breed = await prisma.poultryBreed.findFirst({ where: { id, userId } }); if (!breed) throw new Error("Порода не найдена"); return prisma.poultryBreed.update({ where: { id }, data: { sortOrder: { increment: direction === "UP" ? -11 : 11 } } }); }
function subtractDays(value: Date, days: number) { const result = new Date(value); result.setUTCDate(result.getUTCDate() - days); return result; }
export function reportRange(period: PoultryPeriod, today = dateFromInput(todayInputValue())) { return period === "ALL" ? { from: new Date("1970-01-01T00:00:00.000Z"), to: today } : { from: periodStart(period, today), to: today }; }
async function activeBatch(db: Db, userId: string, id: string) { const batch = await db.poultryBatch.findFirst({ where: { id, userId, status: "ACTIVE", deletedAt: null } }); if (!batch) throw new Error("Активну групу не знайдено."); return batch; }
async function syncBatchQuantity(db: Db, batchId: string) { const batch = await db.poultryBatch.findUniqueOrThrow({ where: { id: batchId }, select: { startingQuantity: true } }); const rows = await db.poultryMovement.findMany({ where: { batchId, deletedAt: null }, select: { quantity: true, quantityDelta: true, type: true } }); const currentQuantity = flockQuantity(batch.startingQuantity, rows.map((row) => row.quantityDelta ?? movementDelta(row.type, row.quantity))); await db.poultryBatch.update({ where: { id: batchId }, data: { currentQuantity } }); return currentQuantity; }
async function originBalances(db: Db, batchId: string) { const rows = await db.poultryOriginMovement.findMany({ where: { batchId, deletedAt: null }, orderBy: { createdAt: "asc" } }); const values = new Map<string, number>(); for (const row of rows) values.set(row.originId, (values.get(row.originId) ?? 0) + row.quantityDelta); return [...values.entries()].filter(([, quantity]) => quantity > 0).map(([originId, quantity]) => ({ originId, quantity })); }
async function allocateOriginOutflow(db: Db, batchId: string, movementId: string, quantity: number, operationDate: Date) { let remaining = quantity; for (const balance of await originBalances(db, batchId)) { if (!remaining) break; const allocated = Math.min(balance.quantity, remaining); await db.poultryOriginMovement.create({ data: { originId: balance.originId, batchId, movementId, quantityDelta: -allocated, operationDate } }); remaining -= allocated; } if (remaining) throw new Error("Історія походження не відповідає поголівʼю. Виконайте звірку."); }
async function createOutflowMovement(db: Db, userId: string, batchId: string, type: PoultryMovementType, quantity: number, operationDate: Date, options: { comment?: string | null; reason?: string | null; saleId?: string; transferId?: string } = {}) { const batch = await activeBatch(db, userId, batchId); if (batch.currentQuantity < quantity) throw new Error("Недостатньо птиці в групі."); const movement = await db.poultryMovement.create({ data: { userId, batchId, type, quantity, quantityDelta: -quantity, operationDate, reason: options.reason, comment: options.comment, saleId: options.saleId, transferId: options.transferId } }); await allocateOriginOutflow(db, batchId, movement.id, quantity, operationDate); await syncBatchQuantity(db, batchId); return movement; }
async function removeMovementEffects(db: Db, movementId: string) { const movement = await db.poultryMovement.findUnique({ where: { id: movementId } }); if (!movement || movement.deletedAt) return movement?.batchId ?? null; const deletedAt = new Date(); await db.poultryOriginMovement.updateMany({ where: { movementId, deletedAt: null }, data: { deletedAt } }); await db.poultryMovement.update({ where: { id: movementId }, data: { deletedAt } }); await syncBatchQuantity(db, movement.batchId); return movement.batchId; }

async function averageFeedCostPerKg(userId: string, productId: string, db: Db | typeof prisma = prisma) { const lots = await db.feedLot.findMany({ where: { userId, productId, deletedAt: null, purchaseTransaction: { deletedAt: null } }, select: { purchasedKg: true, costPerKg: true } }); const kg = lots.reduce((sum, lot) => sum + numberValue(lot.purchasedKg), 0); return kg ? lots.reduce((sum, lot) => sum + numberValue(lot.purchasedKg) * numberValue(lot.costPerKg), 0) / kg : 0; }
export async function batchProductionCost(userId: string, batchId: string, asOf = dateFromInput(todayInputValue()), db: Db | typeof prisma = prisma) { const [entries, usages, rates, expenses] = await Promise.all([db.poultryCostEntry.findMany({ where: { userId, batchId, deletedAt: null, operationDate: { lte: asOf } } }), db.feedUsage.findMany({ where: { batchId, deletedAt: null, operationDate: { lte: asOf } }, include: { lot: true } }), db.feedRate.findMany({ where: { userId, batchId, deletedAt: null, effectiveFrom: { lte: asOf } }, orderBy: { effectiveFrom: "asc" } }), db.poultryOperationalExpense.findMany({ where: { userId, batchId, deletedAt: null, transaction: { deletedAt: null, operationDate: { lte: asOf }, category: { name: { notIn: ["Оборудование", "Обладнання і матеріали"] } } } }, include: { transaction: true } })]); const baseCost = entries.reduce((sum, entry) => sum + numberValue(entry.amount), 0); const manualFeedCost = usages.reduce((sum, usage) => sum + numberValue(usage.costAmount ?? usage.lot.costPerBag.mul(usage.bags)), 0); let estimatedFeedCost = 0; const manuallyCostedProducts = new Set(usages.map((usage) => usage.lot.productId)); const byProduct = new Map<string, typeof rates>(); for (const rate of rates) byProduct.set(rate.productId, [...(byProduct.get(rate.productId) ?? []), rate]); for (const [productId, productRates] of byProduct) if (!manuallyCostedProducts.has(productId)) estimatedFeedCost += approximateFeedConsumptionKg(productRates.map((rate) => ({ dailyKg: numberValue(rate.dailyKg), effectiveFrom: rate.effectiveFrom })), productRates[0].effectiveFrom, asOf) * await averageFeedCostPerKg(userId, productId, db); const directExpenses = expenses.reduce((sum, expense) => sum + numberValue(expense.transaction.amount), 0); return { baseCost, manualFeedCost, estimatedFeedCost, feedCost: manualFeedCost + estimatedFeedCost, directExpenses, total: baseCost + manualFeedCost + estimatedFeedCost + directExpenses }; }

export async function createPoultryBatch(userId: string, input: z.infer<typeof batchSchema>) { const acquisitionDate = dateFromInput(input.acquisitionDate ?? input.startDate); const originDate = input.ageAtAcquisitionDays ? subtractDays(acquisitionDate, input.ageAtAcquisitionDays) : dateFromInput(input.startDate); const cashCost = input.source === "PURCHASE" ? decimal(input.cashCost ?? "0") : decimal(0); const productionCost = input.source === "PURCHASE" ? cashCost : decimal(input.productionValue ?? "0"); const breeds = input.breeds?.length ? input.breeds : [{ name: input.breed ?? "Неизвестно", quantity: input.quantity }]; if (breeds.reduce((sum, item) => sum + item.quantity, 0) !== input.quantity) throw new Error("Сума породного складу має дорівнювати кількості групи."); const category = cashCost.gt(0) ? await categoryByName(userId, ["Покупка птиці", "Покупка птицы"], "EXPENSE") : null; return prisma.$transaction(async (db) => { const transaction = category ? await db.transaction.create({ data: { userId, type: "EXPENSE", amount: cashCost, operationDate: acquisitionDate, module: "POULTRY", categoryId: category.id, description: `Покупка птицы: ${input.name}`, source: "WEB" } }) : null; const batch = await db.poultryBatch.create({ data: { userId, name: input.name, birdType: input.birdType, breed: input.breed ?? null, startDate: originDate, acquisitionDate, ageAtAcquisitionDays: input.ageAtAcquisitionDays, startingQuantity: input.quantity, currentQuantity: input.quantity, source: input.source, comment: input.comment, acquisitionCashCost: cashCost, acquisitionProductionCost: productionCost, acquisitionTransactionId: transaction?.id, breeds: { create: breeds.map((item) => ({ name: item.name || "Неизвестно", quantity: item.quantity })) } } }); const origin = await db.poultryOrigin.create({ data: { userId, type: input.source, birdType: input.birdType, originDate, initialQuantity: input.quantity, description: input.comment } }); await db.poultryOriginMovement.create({ data: { originId: origin.id, batchId: batch.id, quantityDelta: input.quantity, operationDate: acquisitionDate } }); if (productionCost.gt(0)) await db.poultryCostEntry.create({ data: { userId, batchId: batch.id, type: "ACQUISITION", amount: productionCost, operationDate: acquisitionDate, referenceId: transaction?.id } }); return batch; }); }

export async function createPoultryMovement(userId: string, input: z.infer<typeof movementSchema>) { return prisma.$transaction(async (db) => { const operationDate = dateFromInput(input.operationDate); if (input.type === "ADD") { const batch = await activeBatch(db, userId, input.batchId); const movement = await db.poultryMovement.create({ data: { userId, batchId: batch.id, type: "ADD", quantity: input.quantity, quantityDelta: input.quantity, operationDate, reason: input.reason, comment: input.comment } }); const origin = await db.poultryOrigin.create({ data: { userId, type: "OTHER", birdType: batch.birdType, originDate: operationDate, initialQuantity: input.quantity, description: input.comment } }); await db.poultryOriginMovement.create({ data: { originId: origin.id, batchId: batch.id, movementId: movement.id, quantityDelta: input.quantity, operationDate } }); await syncBatchQuantity(db, batch.id); return movement; } if (input.type === "ADJUSTMENT") { const movement = await db.poultryMovement.create({ data: { userId, batchId: input.batchId, type: "ADJUSTMENT", quantity: input.quantity, quantityDelta: input.quantity, operationDate, reason: input.reason, comment: input.comment } }); await syncBatchQuantity(db, input.batchId); return movement; } return createOutflowMovement(db, userId, input.batchId, input.type, input.quantity, operationDate, { reason: input.reason, comment: input.comment }); }); }

export async function reconcileFlock(userId: string, input: z.infer<typeof reconciliationSchema>) { return prisma.$transaction(async (db) => { const batch = await activeBatch(db, userId, input.batchId); const delta = reconciliationDelta(batch.currentQuantity, input.actualQuantity); if (!delta) throw new Error("Поголівʼя вже збігається."); const operationDate = dateFromInput(input.operationDate); const movement = await db.poultryMovement.create({ data: { userId, batchId: batch.id, type: "ADJUSTMENT", quantity: Math.abs(delta), quantityDelta: delta, operationDate, reason: "Физический пересчёт", comment: input.comment } }); if (delta < 0) await allocateOriginOutflow(db, batch.id, movement.id, Math.abs(delta), operationDate); else { const origin = await db.poultryOrigin.create({ data: { userId, type: "OTHER", birdType: batch.birdType, originDate: operationDate, initialQuantity: delta, description: "Добавлено при сверке" } }); await db.poultryOriginMovement.create({ data: { originId: origin.id, batchId: batch.id, movementId: movement.id, quantityDelta: delta, operationDate } }); } await syncBatchQuantity(db, batch.id); return movement; }); }

export async function createPoultryTransfer(userId: string, input: z.infer<typeof transferSchema>) { return prisma.$transaction(async (db) => { const source = await activeBatch(db, userId, input.sourceBatchId); if (source.currentQuantity < input.quantity) throw new Error("Недостатньо птиці для переведення."); const operationDate = dateFromInput(input.operationDate); const cost = await batchProductionCost(userId, source.id, operationDate, db); const transferredCost = transferProductionCost(cost.total, source.currentQuantity, input.quantity); let destination = input.destinationBatchId ? await activeBatch(db, userId, input.destinationBatchId) : null; if (destination?.id === source.id) throw new Error("Оберіть іншу групу."); if (!destination) destination = await db.poultryBatch.create({ data: { userId, name: input.destinationName!, birdType: source.birdType, breed: source.breed, startDate: source.startDate, acquisitionDate: operationDate, startingQuantity: 0, currentQuantity: 0, source: source.source, comment: `Создана переводом из ${source.name}` } }); const transfer = await db.poultryTransfer.create({ data: { userId, sourceBatchId: source.id, destinationBatchId: destination.id, quantity: input.quantity, transferredCost: decimal(transferredCost), operationDate, comment: input.comment } }); const sourceMovement = await db.poultryMovement.create({ data: { userId, batchId: source.id, type: "TRANSFER", quantity: input.quantity, quantityDelta: -input.quantity, operationDate, comment: input.comment, transferId: transfer.id } }); const destinationMovement = await db.poultryMovement.create({ data: { userId, batchId: destination.id, type: "ADD", quantity: input.quantity, quantityDelta: input.quantity, operationDate, comment: `Переведено из ${source.name}`, transferId: transfer.id } }); let remaining = input.quantity; for (const balance of await originBalances(db, source.id)) { if (!remaining) break; const moved = Math.min(balance.quantity, remaining); await db.poultryOriginMovement.createMany({ data: [{ originId: balance.originId, batchId: source.id, movementId: sourceMovement.id, quantityDelta: -moved, operationDate }, { originId: balance.originId, batchId: destination.id, movementId: destinationMovement.id, quantityDelta: moved, operationDate }] }); remaining -= moved; } if (remaining) throw new Error("Не вдалося перенести історію походження."); await db.poultryCostEntry.createMany({ data: [{ userId, batchId: source.id, type: "TRANSFER_OUT", amount: decimal(-transferredCost), referenceId: transfer.id, operationDate, comment: input.comment }, { userId, batchId: destination.id, type: "TRANSFER_IN", amount: decimal(transferredCost), referenceId: transfer.id, operationDate, comment: input.comment }] }); await Promise.all([syncBatchQuantity(db, source.id), syncBatchQuantity(db, destination.id)]); return transfer; }); }

export async function createSlaughter(userId: string, input: z.infer<typeof slaughterSchema>) { return prisma.$transaction(async (db) => { const operationDate = dateFromInput(input.operationDate); const movement = await createOutflowMovement(db, userId, input.batchId, "FAMILY_USE", input.quantity, operationDate, { comment: input.comment, reason: input.purpose === "FAMILY" ? "Для семьи" : "На продажу" }); return db.poultrySlaughter.create({ data: { userId, batchId: input.batchId, quantity: input.quantity, purpose: input.purpose, carcassWeightKg: input.carcassWeightKg ? decimal(input.carcassWeightKg) : null, operationDate, comment: input.comment, movementId: movement.id } }); }); }

async function applySaleStock(db: Db, userId: string, sale: { id: string; saleType: PoultrySaleType; batchId: string | null; requestedSlaughterId?: string | null; quantity: number | null; operationDate: Date; comment: string | null }) { if (sale.saleType === "LIVE_BIRD" && sale.batchId && sale.quantity) return { movement: await createOutflowMovement(db, userId, sale.batchId, "SALE", sale.quantity, sale.operationDate, { comment: sale.comment, saleId: sale.id }), slaughter: null, autoSlaughter: false }; if (sale.saleType === "CARCASS") { if (sale.requestedSlaughterId) { const slaughter = await db.poultrySlaughter.findFirst({ where: { id: sale.requestedSlaughterId, userId, deletedAt: null } }); if (!slaughter) throw new Error("Забій не знайдено."); return { movement: null, slaughter, autoSlaughter: false }; } if (!sale.batchId || !sale.quantity) throw new Error("Для тушки оберіть групу й кількість або готовий забій."); const movement = await createOutflowMovement(db, userId, sale.batchId, "FAMILY_USE", sale.quantity, sale.operationDate, { comment: sale.comment, reason: "Забой на продажу" }); const slaughter = await db.poultrySlaughter.create({ data: { userId, batchId: sale.batchId, quantity: sale.quantity, purpose: "SALE", operationDate: sale.operationDate, comment: sale.comment, movementId: movement.id } }); return { movement, slaughter, autoSlaughter: true }; } return { movement: null, slaughter: null, autoSlaughter: false }; }
async function removeSaleStock(db: Db, sale: { movement: { id: string } | null; slaughter: { id: string; movementId: string } | null; autoSlaughter: boolean }) { if (sale.movement) { await removeMovementEffects(db, sale.movement.id); await db.poultryMovement.update({ where: { id: sale.movement.id }, data: { saleId: null } }); } if (sale.autoSlaughter && sale.slaughter) { await removeMovementEffects(db, sale.slaughter.movementId); await db.poultrySlaughter.updateMany({ where: { id: sale.slaughter.id, deletedAt: null }, data: { deletedAt: new Date() } }); } }

export async function createPoultrySale(userId: string, input: z.infer<typeof saleSchema>) { const totalAmount = saleTotal(input.quantity, input.weightKg, input.price, input.totalAmount); const category = await categoryByName(userId, ["Продаж продукції", "Продажа продукции"], "INCOME"); return prisma.$transaction(async (db) => { const operationDate = dateFromInput(input.operationDate); const income = await db.transaction.create({ data: { userId, type: "INCOME", amount: decimal(totalAmount), operationDate, module: "POULTRY", categoryId: category.id, description: input.itemName, source: "WEB" } }); const sale = await db.poultrySale.create({ data: { userId, saleType: input.saleType, batchId: input.batchId, buyer: input.buyer, buyerPhone: input.buyerPhone, itemName: input.itemName, quantity: input.quantity, weightKg: input.weightKg ? decimal(input.weightKg) : null, price: input.price ? decimal(input.price) : null, totalAmount: decimal(totalAmount), operationDate, comment: input.comment, incomeTransactionId: income.id } }); const stock = await applySaleStock(db, userId, { ...sale, requestedSlaughterId: input.slaughterId }); if (stock.slaughter) await db.poultrySale.update({ where: { id: sale.id }, data: { slaughterId: stock.slaughter.id, autoSlaughter: stock.autoSlaughter } }); return sale; }); }
export async function getPoultrySale(userId: string, id: string) { const sale = await prisma.poultrySale.findFirst({ where: { id, userId, deletedAt: null }, include: { batch: true, slaughter: true } }); if (!sale) throw new Error("Продаж не знайдено."); return sale; }
export async function updatePoultrySale(userId: string, id: string, input: z.infer<typeof saleSchema>) { const totalAmount = saleTotal(input.quantity, input.weightKg, input.price, input.totalAmount); const category = await categoryByName(userId, ["Продаж продукції", "Продажа продукции"], "INCOME"); return prisma.$transaction(async (db) => { const current = await db.poultrySale.findFirst({ where: { id, userId, deletedAt: null }, include: { movement: true, slaughter: true } }); if (!current) throw new Error("Продаж не знайдено."); await removeSaleStock(db, current); const operationDate = dateFromInput(input.operationDate); await db.transaction.update({ where: { id: current.incomeTransactionId }, data: { type: "INCOME", module: "POULTRY", deletedAt: null, amount: decimal(totalAmount), operationDate, categoryId: category.id, description: input.itemName } }); const sale = await db.poultrySale.update({ where: { id }, data: { saleType: input.saleType, batchId: input.batchId, buyer: input.buyer, buyerPhone: input.buyerPhone, itemName: input.itemName, quantity: input.quantity, weightKg: input.weightKg ? decimal(input.weightKg) : null, price: input.price ? decimal(input.price) : null, totalAmount: decimal(totalAmount), operationDate, comment: input.comment, slaughterId: null, autoSlaughter: false } }); const stock = await applySaleStock(db, userId, { ...sale, requestedSlaughterId: input.slaughterId }); if (stock.slaughter) await db.poultrySale.update({ where: { id }, data: { slaughterId: stock.slaughter.id, autoSlaughter: stock.autoSlaughter } }); return sale; }); }
export async function softDeletePoultrySale(userId: string, id: string) { return prisma.$transaction(async (db) => { const sale = await db.poultrySale.findFirst({ where: { id, userId, deletedAt: null }, include: { movement: true, slaughter: true } }); if (!sale) throw new Error("Продаж не знайдено."); await removeSaleStock(db, sale); const deletedAt = new Date(); await db.transaction.update({ where: { id: sale.incomeTransactionId }, data: { deletedAt } }); return db.poultrySale.update({ where: { id }, data: { deletedAt } }); }); }

export async function createFeedPurchase(userId: string, input: z.infer<typeof feedPurchaseSchema>) { const category = await categoryByName(userId, ["Корма", "Корм"], "EXPENSE"); const quantity = Number((input.quantity ?? String(input.bags ?? 0)).replace(",", ".")); return prisma.$transaction(async (db) => { const existing = await db.feedProduct.findUnique({ where: { userId_name: { userId, name: input.name } } }); const bagSize = input.bagSizeKg ? Number(input.bagSizeKg.replace(",", ".")) : numberValue(existing?.bagSizeKg); const householdKg = input.householdUnitKg ? Number(input.householdUnitKg.replace(",", ".")) : numberValue(existing?.householdUnitKg); const purchasedKg = feedQuantityToKg(quantity, input.unit, { bagSizeKg: bagSize, householdUnitKg: householdKg }); const goodsAmount = decimal(input.totalAmount); const deliveryAmount = decimal(input.deliveryAmount ?? "0"); const totalAmount = goodsAmount.plus(deliveryAmount); const product = await db.feedProduct.upsert({ where: { userId_name: { userId, name: input.name } }, update: { type: input.type, bagSizeKg: bagSize ? decimal(bagSize) : null, householdUnitName: input.householdUnitName, householdUnitKg: householdKg ? decimal(householdKg) : null }, create: { userId, name: input.name, type: input.type, bagSizeKg: bagSize ? decimal(bagSize) : null, householdUnitName: input.householdUnitName, householdUnitKg: householdKg ? decimal(householdKg) : null } }); const transaction = await db.transaction.create({ data: { userId, type: "EXPENSE", amount: totalAmount, operationDate: dateFromInput(input.operationDate), module: "POULTRY", categoryId: category.id, description: `Корм: ${input.name}`, source: "WEB" } }); const bags = input.unit === "BAG" ? Math.round(quantity) : 0; return db.feedLot.create({ data: { userId, productId: product.id, purchaseTransactionId: transaction.id, purchasedBags: bags, availableBags: bags, costPerBag: input.unit === "BAG" ? totalAmount.div(quantity) : totalAmount, purchaseUnit: input.unit, purchaseQuantity: decimal(quantity), purchasedKg: decimal(purchasedKg), availableKg: decimal(purchasedKg), costPerKg: totalAmount.div(purchasedKg), deliveryAmount, supplier: input.supplier, purchaseDate: dateFromInput(input.operationDate), comment: input.comment } }); }); }
export async function createFeedUsage(userId: string, input: z.infer<typeof feedUsageSchema> & { type?: "ASSIGNED" | "FINISHED" }) { return prisma.$transaction(async (db) => { const lot = await db.feedLot.findFirst({ where: { id: input.lotId, userId, deletedAt: null }, include: { product: true } }); const batch = input.batchId ? await activeBatch(db, userId, input.batchId) : null; if (!lot) throw new Error("Корм не знайдено."); const quantity = Number((input.quantity ?? String(input.bags ?? 0)).replace(",", ".")); const quantityKg = feedQuantityToKg(quantity, input.unit, { bagSizeKg: numberValue(lot.product.bagSizeKg), householdUnitKg: numberValue(lot.product.householdUnitKg) }); const stock = await calculatedProductStockKg(userId, lot.productId, dateFromInput(input.operationDate), db); if (stock.current < quantityKg) throw new Error("На складі недостатньо корму."); const costAmount = lot.costPerKg ? lot.costPerKg.mul(quantityKg) : lot.costPerBag.mul(input.unit === "BAG" ? quantity : 0); const usage = await db.feedUsage.create({ data: { lotId: lot.id, batchId: batch?.id, purpose: input.purpose, bags: input.unit === "BAG" ? Math.round(quantity) : 0, unit: input.unit, quantity: decimal(quantity), quantityKg: decimal(quantityKg), costAmount, type: input.type ?? "ASSIGNED", operationDate: dateFromInput(input.operationDate), comment: input.comment } }); await db.feedLot.update({ where: { id: lot.id }, data: { availableKg: lot.availableKg == null ? null : lot.availableKg.minus(quantityKg), availableBags: input.unit === "BAG" ? Math.max(0, lot.availableBags - Math.round(quantity)) : lot.availableBags } }); return usage; }); }
export async function createFeedRate(userId: string, input: z.infer<typeof feedRateSchema>) { const [batch, product] = await Promise.all([prisma.poultryBatch.findFirst({ where: { id: input.batchId, userId, deletedAt: null } }), prisma.feedProduct.findFirst({ where: { id: input.productId, userId } })]); if (!batch || !product) throw new Error("Корм або групу не знайдено."); const dailyQuantity = Number(input.dailyQuantity.replace(",", ".")); const dailyKg = feedQuantityToKg(dailyQuantity, input.unit, { bagSizeKg: numberValue(product.bagSizeKg), householdUnitKg: numberValue(product.householdUnitKg) }); return prisma.feedRate.create({ data: { userId, batchId: batch.id, productId: product.id, dailyQuantity: decimal(dailyQuantity), unit: input.unit, dailyKg: decimal(dailyKg), effectiveFrom: dateFromInput(input.effectiveFrom), comment: input.comment } }); }

export async function calculatedProductStockKg(userId: string, productId: string, asOf: Date, db: Db | typeof prisma = prisma) { const [lots, usages, adjustments, rates] = await Promise.all([db.feedLot.findMany({ where: { userId, productId, deletedAt: null, purchaseDate: { lte: asOf }, purchaseTransaction: { deletedAt: null } } }), db.feedUsage.findMany({ where: { lot: { userId, productId }, deletedAt: null, operationDate: { lte: asOf } } }), db.feedInventoryAdjustment.findMany({ where: { userId, productId, deletedAt: null, operationDate: { lte: asOf } } }), db.feedRate.findMany({ where: { userId, productId, deletedAt: null, effectiveFrom: { lte: asOf } }, orderBy: [{ batchId: "asc" }, { effectiveFrom: "asc" }] })]); const purchased = lots.reduce((sum, lot) => sum + numberValue(lot.purchasedKg), 0); const manual = usages.reduce((sum, usage) => sum + numberValue(usage.quantityKg), 0); let estimated = 0; const manuallyTrackedBatches = new Set(usages.map((usage) => usage.batchId)); const byBatch = new Map<string, typeof rates>(); for (const rate of rates) byBatch.set(rate.batchId, [...(byBatch.get(rate.batchId) ?? []), rate]); for (const [batchId, batchRates] of byBatch) if (!manuallyTrackedBatches.has(batchId)) estimated += approximateFeedConsumptionKg(batchRates.map((rate) => ({ dailyKg: numberValue(rate.dailyKg), effectiveFrom: rate.effectiveFrom })), batchRates[0].effectiveFrom, asOf); const adjustment = adjustments.reduce((sum, item) => sum + numberValue(item.quantityDeltaKg), 0); return { purchased, manual, estimated, adjustment, current: purchased - manual - estimated + adjustment }; }
export async function createFeedAdjustment(userId: string, input: z.infer<typeof feedAdjustmentSchema>) { const product = await prisma.feedProduct.findFirst({ where: { id: input.productId, userId } }); if (!product) throw new Error("Корм не знайдено."); const operationDate = dateFromInput(input.operationDate); const stock = await calculatedProductStockKg(userId, product.id, operationDate); const actual = Number(input.actualKg.replace(",", ".")); return prisma.feedInventoryAdjustment.create({ data: { userId, productId: product.id, calculatedKg: decimal(stock.current), actualKg: decimal(actual), quantityDeltaKg: decimal(reconciliationDelta(stock.current, actual)), operationDate, comment: input.comment } }); }
export async function updateFeedProductSettings(userId: string, input: z.infer<typeof feedProductSettingsSchema>) { const product = await prisma.feedProduct.findFirst({ where: { id: input.productId, userId } }); if (!product) throw new Error("Корм не знайдено."); return prisma.feedProduct.update({ where: { id: product.id }, data: { type: input.type, minimumStockKg: decimal(input.minimumStockKg) } }); }
export async function updateFeedUnitSettings(userId: string, input: z.infer<typeof feedUnitSettingsSchema>) { const product = await prisma.feedProduct.findFirst({ where: { id: input.productId, userId } }); if (!product) throw new Error("Корм не найден"); return prisma.feedProduct.update({ where: { id: product.id }, data: { bagSizeKg: input.bagSizeKg ? decimal(input.bagSizeKg) : null, householdUnitName: input.householdUnitName, householdUnitKg: input.householdUnitKg ? decimal(input.householdUnitKg) : null } }); }

export async function getFeedProducts(userId: string) { return prisma.feedProduct.findMany({ where: { userId }, include: { _count: { select: { lots: true, rates: true, adjustments: true } } }, orderBy: { name: "asc" } }); }
async function assertUniqueFeedProduct(userId: string, name: string, exceptId?: string) { const products = await prisma.feedProduct.findMany({ where: { userId, ...(exceptId ? { id: { not: exceptId } } : {}) }, select: { name: true } }); if (products.some((item) => canonicalName(item.name) === canonicalName(name))) throw new Error("Такой вид корма уже существует"); }
export async function createFeedProduct(userId: string, input: z.infer<typeof feedProductCatalogSchema>) { const name = normalizedName(input.name); await assertUniqueFeedProduct(userId, name); return prisma.feedProduct.create({ data: { userId, name, type: input.type, minimumStockKg: decimal(0) } }); }
export async function updateFeedProductCatalog(userId: string, input: z.infer<typeof feedProductCatalogSchema>) { if (!input.id) throw new Error("Корм не найден"); const product = await prisma.feedProduct.findFirst({ where: { id: input.id, userId } }); if (!product) throw new Error("Корм не найден"); const name = normalizedName(input.name); await assertUniqueFeedProduct(userId, name, product.id); return prisma.feedProduct.update({ where: { id: product.id }, data: { name, type: input.type } }); }
export async function deleteUnusedFeedProduct(userId: string, id: string) { const product = await prisma.feedProduct.findFirst({ where: { id, userId }, include: { _count: { select: { lots: true, rates: true, adjustments: true } } } }); if (!product) throw new Error("Корм не найден"); if (product._count.lots || product._count.rates || product._count.adjustments) throw new Error("Этот корм используется в истории и не может быть удалён"); return prisma.feedProduct.delete({ where: { id } }); }

export async function getFeedWorkspace(userId: string) {
  const [dashboard, products] = await Promise.all([getPoultryDashboard(userId), prisma.feedProduct.findMany({ where: { userId }, orderBy: { name: "asc" } })]);
  const [usages, adjustments, rates] = await Promise.all([
    prisma.feedUsage.findMany({ where: { deletedAt: null, lot: { userId, deletedAt: null } }, include: { lot: { include: { product: true } }, batch: true }, orderBy: { operationDate: "desc" } }),
    prisma.feedInventoryAdjustment.findMany({ where: { userId, deletedAt: null }, include: { product: true }, orderBy: { operationDate: "desc" } }),
    prisma.feedRate.findMany({ where: { userId, deletedAt: null }, orderBy: { effectiveFrom: "desc" } }),
  ]);
  const latestRates = new Map<string, number>();
  for (const rate of rates) { const key = `${rate.batchId}:${rate.productId}`; if (!latestRates.has(key)) latestRates.set(key, numberValue(rate.dailyKg)); }
  const dailyKg = [...latestRates.values()].reduce((sum, value) => sum + value, 0);
  const includedProductIds = new Set(dashboard.inventory.map((item) => item.product.id));
  const emptyInventory = await Promise.all(products.filter((product) => !includedProductIds.has(product.id)).map(async (product) => ({ product, ...(await calculatedProductStockKg(userId, product.id, dashboard.to)), averageCostPerKg: await averageFeedCostPerKg(userId, product.id) })));
  const inventory = [...dashboard.inventory, ...emptyInventory];
  const operations = [
    ...dashboard.lots.map((lot) => ({ id: `purchase:${lot.id}`, kind: "PURCHASE" as const, date: lot.purchaseDate, productId: lot.productId, productName: lot.product.name, quantityKg: numberValue(lot.purchasedKg), detail: lot.supplier || "Покупка" })),
    ...usages.map((usage) => ({ id: `usage:${usage.id}`, kind: "USAGE" as const, date: usage.operationDate, productId: usage.lot.productId, productName: usage.lot.product.name, quantityKg: -numberValue(usage.quantityKg), detail: usage.batch?.name || (usage.purpose === "FATTENING" ? "Птица на откорм" : usage.purpose === "LAYERS" ? "Несушки" : "Общее использование") })),
    ...adjustments.map((item) => ({ id: `adjustment:${item.id}`, kind: "ADJUSTMENT" as const, date: item.operationDate, productId: item.productId, productName: item.product.name, quantityKg: numberValue(item.quantityDeltaKg), detail: item.comment || "Инвентаризация" })),
  ].sort((a, b) => b.date.getTime() - a.date.getTime());
  return { ...dashboard, inventory, operations, dailyKg };
}

export async function createIncubationBatch(userId: string, input: z.infer<typeof incubationSchema>) { const cashCost = input.eggSource === "PURCHASED" ? decimal(input.cashCost ?? "0") : decimal(0); const productionCost = input.eggSource === "PURCHASED" ? cashCost : decimal(input.productionCost ?? "0"); const category = cashCost.gt(0) ? await categoryByName(userId, ["Инкубационные яйца", "Інкубаційні яйця"], "EXPENSE") : null; return prisma.$transaction(async (db) => { const transaction = category ? await db.transaction.create({ data: { userId, type: "EXPENSE", amount: cashCost, operationDate: dateFromInput(input.setDate), module: "POULTRY", categoryId: category.id, description: `Инкубационные яйца: ${input.name}`, source: "WEB" } }) : null; return db.incubationBatch.create({ data: { userId, name: input.name, birdType: input.birdType, setDate: dateFromInput(input.setDate), eggSource: input.eggSource, cashCost, productionCost, expenseTransactionId: transaction?.id, comment: input.comment, items: { create: input.items } }, include: { items: true } }); }); }
export async function updateIncubationItem(userId: string, input: z.infer<typeof incubationUpdateSchema>) { const item = await prisma.incubationBatchItem.findFirst({ where: { id: input.itemId, deletedAt: null, incubationBatch: { userId, deletedAt: null } } }); if (!item || input.infertileQuantity + input.lossQuantity + input.hatchedQuantity > item.setQuantity) throw new Error("Показники інкубації перевищують закладену кількість."); return prisma.$transaction(async (db) => { const updated = await db.incubationBatchItem.update({ where: { id: input.itemId }, data: { infertileQuantity: input.infertileQuantity, lossQuantity: input.lossQuantity, hatchedQuantity: input.hatchedQuantity } }); await db.incubationBatch.update({ where: { id: item.incubationBatchId }, data: { hatchDate: dateFromInput(input.hatchDate), status: "COMPLETED" } }); return updated; }); }
export async function createBatchFromIncubation(userId: string, itemId: string) { return prisma.$transaction(async (db) => { const item = await db.incubationBatchItem.findFirst({ where: { id: itemId, deletedAt: null, poultryBatch: null, incubationBatch: { userId, deletedAt: null } }, include: { incubationBatch: true } }); if (!item || item.hatchedQuantity < 1 || !item.incubationBatch.hatchDate) throw new Error("Спочатку вкажіть фактичну дату й результат виводу."); const result = await db.incubationBatchItem.aggregate({ where: { incubationBatchId: item.incubationBatchId, deletedAt: null }, _sum: { hatchedQuantity: true } }); const allocatedCost = item.incubationBatch.productionCost.mul(item.hatchedQuantity).div(result._sum.hatchedQuantity || item.hatchedQuantity); const batch = await db.poultryBatch.create({ data: { userId, name: `${item.incubationBatch.name}${item.breed ? ` · ${item.breed}` : ""}`, birdType: item.incubationBatch.birdType, breed: item.breed, startDate: item.incubationBatch.hatchDate, acquisitionDate: item.incubationBatch.hatchDate, startingQuantity: item.hatchedQuantity, currentQuantity: item.hatchedQuantity, source: "INCUBATION", incubationBatchId: item.incubationBatchId, incubationItemId: item.id, acquisitionProductionCost: allocatedCost, comment: `Создано из инкубации ${item.incubationBatch.name}`, breeds: { create: { name: item.breed || "Неизвестно", quantity: item.hatchedQuantity } } } }); const origin = await db.poultryOrigin.create({ data: { userId, type: "INCUBATION", birdType: item.incubationBatch.birdType, originDate: item.incubationBatch.hatchDate, initialQuantity: item.hatchedQuantity, description: item.incubationBatch.name } }); await db.poultryOriginMovement.create({ data: { originId: origin.id, batchId: batch.id, quantityDelta: item.hatchedQuantity, operationDate: item.incubationBatch.hatchDate } }); if (allocatedCost.gt(0)) await db.poultryCostEntry.create({ data: { userId, batchId: batch.id, type: "INCUBATION_EGGS", amount: allocatedCost, referenceId: item.incubationBatchId, operationDate: item.incubationBatch.hatchDate } }); return batch; }); }

export async function createEggCollection(userId: string, input: z.infer<typeof eggCollectionSchema>) { if (input.batchId && !await prisma.poultryBatch.findFirst({ where: { id: input.batchId, userId, deletedAt: null } })) throw new Error("Групу не знайдено."); return prisma.poultryEggCollection.create({ data: { userId, batchId: input.batchId, breed: input.breed, quantity: input.quantity, operationDate: dateFromInput(input.operationDate), collector: input.collector, comment: input.comment } }); }
export async function softDeleteEggCollection(userId: string, id: string) { const item = await prisma.poultryEggCollection.findFirst({ where: { id, userId, deletedAt: null } }); if (!item) throw new Error("Збір яєць не знайдено."); return prisma.poultryEggCollection.update({ where: { id }, data: { deletedAt: new Date() } }); }
export async function createOperationalExpense(userId: string, input: z.infer<typeof operationalExpenseSchema>) { await poultryCategory(userId, input.categoryId, "EXPENSE"); if (input.batchId && !await prisma.poultryBatch.findFirst({ where: { id: input.batchId, userId, deletedAt: null } })) throw new Error("Групу не знайдено."); if (input.incubationBatchId && !await prisma.incubationBatch.findFirst({ where: { id: input.incubationBatchId, userId, deletedAt: null } })) throw new Error("Інкубацію не знайдено."); return prisma.$transaction(async (db) => { const transaction = await db.transaction.create({ data: { userId, type: "EXPENSE", amount: decimal(input.amount), operationDate: dateFromInput(input.operationDate), module: "POULTRY", categoryId: input.categoryId, description: input.description, source: "WEB" } }); return db.poultryOperationalExpense.create({ data: { userId, transactionId: transaction.id, batchId: input.batchId, incubationBatchId: input.incubationBatchId } }); }); }
export async function softDeleteOperationalExpense(userId: string, id: string) { return prisma.$transaction(async (db) => { const expense = await db.poultryOperationalExpense.findFirst({ where: { id, userId, deletedAt: null } }); if (!expense) throw new Error("Витрату не знайдено."); const deletedAt = new Date(); await db.transaction.update({ where: { id: expense.transactionId }, data: { deletedAt } }); return db.poultryOperationalExpense.update({ where: { id }, data: { deletedAt } }); }); }

export async function getPoultryDashboard(userId: string, period: PoultryPeriod = "MONTH") { const { from, to } = reportRange(period); const [batches, lots, incubations, sales, transactions, eggs, slaughters, transfers, expenses] = await Promise.all([prisma.poultryBatch.findMany({ where: { userId, deletedAt: null }, include: { breeds: { where: { deletedAt: null } }, feedUsages: { where: { deletedAt: null }, include: { lot: { include: { product: true } } } }, feedRates: { where: { deletedAt: null }, include: { product: true }, orderBy: { effectiveFrom: "desc" } }, sales: { where: { deletedAt: null } } }, orderBy: { startDate: "desc" } }), prisma.feedLot.findMany({ where: { userId, deletedAt: null, purchaseTransaction: { deletedAt: null } }, include: { product: true, purchaseTransaction: true }, orderBy: { purchaseDate: "desc" } }), prisma.incubationBatch.findMany({ where: { userId, deletedAt: null }, include: { items: { where: { deletedAt: null }, include: { poultryBatch: true } } }, orderBy: { setDate: "desc" } }), prisma.poultrySale.findMany({ where: { userId, deletedAt: null }, include: { batch: true, slaughter: true }, orderBy: { operationDate: "desc" } }), prisma.transaction.findMany({ where: { userId, module: "POULTRY", type: { in: ["INCOME", "EXPENSE"] }, deletedAt: null, operationDate: { gte: from, lte: to } }, include: { category: true } }), prisma.poultryEggCollection.findMany({ where: { userId, deletedAt: null, operationDate: { gte: from, lte: to } }, include: { batch: true }, orderBy: { operationDate: "desc" } }), prisma.poultrySlaughter.findMany({ where: { userId, deletedAt: null, operationDate: { gte: from, lte: to } } }), prisma.poultryTransfer.findMany({ where: { userId, deletedAt: null, operationDate: { gte: from, lte: to } } }), prisma.poultryOperationalExpense.findMany({ where: { userId, deletedAt: null, transaction: { deletedAt: null } }, include: { transaction: { include: { category: true } }, batch: true, incubationBatch: true }, orderBy: { createdAt: "desc" } })]); const enrichedBatches = await Promise.all(batches.map(async (batch) => ({ ...batch, ageDays: poultryAgeDays(batch.startDate, to), productionCost: await batchProductionCost(userId, batch.id, to), feedCost: batch.feedUsages.reduce((sum, usage) => sum.plus(usage.costAmount ?? usage.lot.costPerBag.mul(usage.bags)), decimal(0)) }))); const products = [...new Map(lots.map((lot) => [lot.productId, lot.product])).values()]; const inventory = await Promise.all(products.map(async (product) => ({ product, ...(await calculatedProductStockKg(userId, product.id, to)), averageCostPerKg: await averageFeedCostPerKg(userId, product.id) }))); return { from, to, report: poultryReport(transactions.map((item) => ({ type: item.type as "INCOME" | "EXPENSE", amount: item.amount.toString(), categoryName: item.category?.name }))), batches: enrichedBatches, lots, inventory, incubations: incubations.map((batch) => ({ ...batch, items: batch.items.map((item) => ({ ...item, hatchRate: hatchRate(item.setQuantity, item.hatchedQuantity) })) })), sales, eggs, slaughters, transfers, expenses }; }

export async function getPoultryAnalytics(userId: string, period: PoultryPeriod = "MONTH", custom?: { from?: string; to?: string }) { const range = custom?.from && custom?.to ? { from: dateFromInput(custom.from), to: dateFromInput(custom.to) } : reportRange(period); const dashboard = await getPoultryDashboard(userId, custom?.from ? "ALL" : period); const [movements, eggs, incubations, transactions] = await Promise.all([prisma.poultryMovement.findMany({ where: { userId, deletedAt: null, operationDate: { gte: range.from, lte: range.to } } }), prisma.poultryEggCollection.findMany({ where: { userId, deletedAt: null, operationDate: { gte: range.from, lte: range.to } } }), prisma.incubationBatch.findMany({ where: { userId, deletedAt: null, setDate: { gte: range.from, lte: range.to } }, include: { items: { where: { deletedAt: null } } } }), prisma.transaction.findMany({ where: { userId, module: "POULTRY", type: { in: ["INCOME", "EXPENSE"] }, deletedAt: null, operationDate: { gte: range.from, lte: range.to } }, include: { category: true } })]); const periodSales = dashboard.sales.filter((sale) => sale.operationDate >= range.from && sale.operationDate <= range.to); const report = poultryReport(transactions.map((item) => ({ type: item.type as "INCOME" | "EXPENSE", amount: item.amount.toString(), categoryName: item.category?.name }))); return { ...dashboard, report, range, flock: { current: dashboard.batches.filter((batch) => batch.status === "ACTIVE").reduce((sum, batch) => sum + batch.currentQuantity, 0), sold: movements.filter((item) => item.type === "SALE").reduce((sum, item) => sum + item.quantity, 0), mortality: movements.filter((item) => item.type === "MORTALITY").reduce((sum, item) => sum + item.quantity, 0), family: movements.filter((item) => item.type === "FAMILY_USE").reduce((sum, item) => sum + item.quantity, 0), transferred: movements.filter((item) => item.type === "TRANSFER").reduce((sum, item) => sum + item.quantity, 0) }, eggStats: { collected: eggs.reduce((sum, item) => sum + item.quantity, 0), sold: periodSales.filter((sale) => sale.saleType === "EGGS").reduce((sum, sale) => sum + (sale.quantity ?? 0), 0), income: periodSales.filter((sale) => sale.saleType === "EGGS").reduce((sum, sale) => sum + Number(sale.totalAmount), 0) }, incubationStats: { count: incubations.length, eggs: incubations.flatMap((item) => item.items).reduce((sum, item) => sum + item.setQuantity, 0), hatched: incubations.flatMap((item) => item.items).reduce((sum, item) => sum + item.hatchedQuantity, 0) } }; }

export function formValue(formData: FormData, name: string) { return optional(formData.get(name)); }
